package com.pulsepay.ledger;
import com.pulsepay.common.ApiException; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class LedgerService {
 private final JdbcTemplate db; public LedgerService(JdbcTemplate db){this.db=db;}
 @Transactional public void postPayment(UUID merchant,UUID payment,long amount,String currency){post(merchant,"payment:"+payment,"payment.captured",currency,amount,"Merchant clearing","Platform processing");}
 @Transactional public void postRefund(UUID merchant,UUID refund,long amount,String currency){post(merchant,"refund:"+refund,"refund.succeeded",currency,amount,"Refund clearing","Merchant clearing");}
 @Transactional public UUID reverse(UUID merchant,String originalReference,String reason){var journals=db.query("select id,currency from ledger_journals where merchant_id=? and transaction_reference=?",(rs,i)->new Object[]{UUID.fromString(rs.getString(1)),rs.getString(2)},merchant,originalReference);if(journals.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"JOURNAL_NOT_FOUND","Ledger journal was not found.");Object[] original=journals.getFirst();String reversalReference="reversal:"+originalReference;if(!db.query("select id from ledger_journals where transaction_reference=?",(rs,i)->rs.getObject(1),reversalReference).isEmpty())throw new ApiException(HttpStatus.CONFLICT,"JOURNAL_ALREADY_REVERSED","This ledger journal has already been reversed.");UUID reversal=UUID.randomUUID();db.update("insert into ledger_journals(id,transaction_reference,merchant_id,event_type,currency)values(?,?,?,'ledger.reversal',?)",reversal,reversalReference,merchant,original[1]);var entries=db.query("select account_id,debit_minor,credit_minor,description from ledger_entries where journal_id=?",(rs,i)->new Object[]{UUID.fromString(rs.getString(1)),rs.getLong(2),rs.getLong(3),rs.getString(4)},original[0]);for(Object[] entry:entries)db.update("insert into ledger_entries(journal_id,account_id,debit_minor,credit_minor,description)values(?,?,?,?,?)",reversal,entry[0],entry[2],entry[1],"Reversal: "+reason+" — "+entry[3]);return reversal;}
 private void post(UUID merchant,String ref,String type,String currency,long amount,String debit,String credit){if(!db.query("select id from ledger_journals where transaction_reference=?",(rs,i)->rs.getObject(1),ref).isEmpty())return;UUID d=account(merchant,debit,currency),c=account(merchant,credit,currency);UUID j=UUID.randomUUID();db.update("insert into ledger_journals(id,transaction_reference,merchant_id,event_type,currency)values(?,?,?,?,?)",j,ref,merchant,type,currency);db.update("insert into ledger_entries(journal_id,account_id,debit_minor,credit_minor,description)values(?,?,?,0,?)",j,d,amount,type);db.update("insert into ledger_entries(journal_id,account_id,debit_minor,credit_minor,description)values(?,?,0,?,?)",j,c,amount,type);Long deb=db.queryForObject("select sum(debit_minor) from ledger_entries where journal_id=?",Long.class,j),cre=db.queryForObject("select sum(credit_minor) from ledger_entries where journal_id=?",Long.class,j);if(!Objects.equals(deb,cre))throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,"UNBALANCED_JOURNAL","Ledger journal is not balanced.");}
 private UUID account(UUID merchant,String name,String currency){var x=db.query("select id from ledger_accounts where merchant_id=? and code=? and currency=?",(rs,i)->UUID.fromString(rs.getString(1)),merchant,name.toUpperCase().replace(' ','_'),currency);if(!x.isEmpty())return x.getFirst();UUID id=UUID.randomUUID();db.update("insert into ledger_accounts(id,merchant_id,code,name,account_type,currency)values(?,?,?,?,?,?)",id,merchant,name.toUpperCase().replace(' ','_'),name,"LIABILITY",currency);return id;}
}

